def icon(name: str, size: int = 16, color: str = None, stroke_width: float = 2,
         vertical_align: str = "-0.15em") -> str:
    """返回一个内联 Fluent Color SVG 图标 HTML 片段。

    Args:
        name: ICONS 中的图标名。
        size: 像素尺寸,默认 16。
        color: 兼容签名,Fluent Color 为固定彩色配色,该参数不再生效。
        stroke_width: 兼容签名,不再生效。
        vertical_align: 与文字基线对齐方式。
    """
    svg = ICONS.get(name)
    if svg is None:
        raise KeyError(f"未知图标: {name}（可用: {sorted(ICONS)}）")
    style = f"width:{size}px;height:{size}px;vertical-align:{vertical_align};"
    return svg.replace("<svg", f'<svg style="{style}"', 1)


def icon_header(title: str, name: str, level: int = 3, size: int = 18) -> str:
    """带图标的节标题（配合 st.markdown(..., unsafe_allow_html=True)）。"""
    if not 1 <= level <= 6:
        raise ValueError("level 须在 1-6 之间")
    return (
        f'<h{level} class="ui-icon-header">'
        f"{icon(name, size=size, vertical_align='-0.18em')}"
        f"<span>{escape(title)}</span></h{level}>"
    )


def icon_line(title: str, name: str, size: int = 15, bold: bool = True) -> str:
    """带图标的一行文段（侧栏状态行等），配合 st.markdown(unsafe_allow_html=True)。"""
    tag_open, tag_close = ("<strong>", "</strong>") if bold else ("", "")
    return (
        '<p class="ui-icon-line" style="margin:0;padding:.2rem 0;">'
        f"{icon(name, size=size)}"
        f"<span>{tag_open}{escape(title)}{tag_close}</span></p>"
    )


def inject_icon_styles() -> None:
    """向页面注入图标组件的基础对齐样式（幂等，多次调用只注入一次）。"""
    import streamlit as st

    marker = "_ui_icon_styles_injected"
    if st.session_state.get(marker):
        return
    st.session_state[marker] = True
    st.markdown(
        """
<style>
/* Bootstrap Reboot 风格的克制基线：只做对齐，不改写 Streamlit 主题 */
.ui-icon-header {
    display: flex;
    align-items: center;
    gap: 0.45em;
    margin-top: 0.75rem;
}
.ui-icon-line { display: flex; align-items: center; gap: 0.55em; }
</style>
""",
        unsafe_allow_html=True,
    )
